// Some portions generated by Claude
import assert from "node:assert/strict";
import test from "node:test";
import { SpatialGrid } from "../../../main/frontend/graph-explorer/spatial-grid.ts";

test('moving rectangles updates cells, oversized entries and stable IDs without stale hits', () => {
  const grid = new SpatialGrid(64), boxes = [];
  for (let i = 0; i < 100; i++) {
    boxes.push({minX: i * 20, minY: 0, maxX: i * 20 + 10, maxY: 10});
    assert.equal(grid.insert(boxes[i]), i);
  }
  for (let i = 0; i < 300; i++) {
    const id = i % 100, x = i * 33 - 2000, width = i % 7 ? 20 : 30000;
    boxes[id] = {minX: x, minY: -200, maxX: x + width, maxY: 150};
    grid.update(id, boxes[id]);
    const query = {minX: -500, minY: -10, maxX: 700, maxY: 10};
    const expected = boxes.flatMap((b, j) => b.maxX >= query.minX && b.minX <= query.maxX && b.maxY >= query.minY && b.minY <= query.maxY ? [j] : []);
    assert.deepEqual(grid.search(query.minX, query.minY, query.maxX, query.maxY), expected);
  }
  assert.throws(() => grid.update(1000, boxes[0]), RangeError);
  assert.throws(() => grid.update(0, {...boxes[0], minX: NaN}), RangeError);
});

test("spatial queries match exhaustive rectangle tests, including touching and negative bounds", () => {
  const grid = new SpatialGrid(64), boxes = [];
  let seed = 813;
  const random = () => ((seed = Math.imul(seed, 1664525) + 1013904223 >>> 0) / 2 ** 32);
  for (let i = 0; i < 500; i++) {
    const minX = Math.floor(random() * 2400 - 1200), minY = Math.floor(random() * 1800 - 900);
    const bounds = {minX, minY, maxX: minX + random() * 300, maxY: minY + random() * 120};
    boxes.push(bounds); grid.insert(bounds);
  }
  boxes.push({minX: -1e9, minY: -1e9, maxX: 1e9, maxY: 1e9}); grid.insert(boxes.at(-1));
  const buffer = [];
  for (const query of [...boxes, {minX: -1e10, minY: -1e10, maxX: 1e10, maxY: 1e10}]) {
    const {minX, minY, maxX, maxY} = query;
    const expected = boxes.flatMap((b, i) => b.maxX >= minX && b.minX <= maxX && b.maxY >= minY && b.minY <= maxY ? [i] : []);
    assert.equal(grid.search(minX, minY, maxX, maxY, buffer), buffer);
    assert.deepEqual(buffer, expected);
  }
});

test("invalid and extreme coordinates cannot create unbounded grid loops", () => {
  assert.throws(() => new SpatialGrid(0), RangeError);
  const grid = new SpatialGrid();
  assert.throws(() => grid.insert({minX: NaN, minY: 0, maxX: 0, maxY: 0}), RangeError);
  grid.insert({minX: 1e30, maxX: 1e30, minY: 1e30, maxY: 1e30});
  assert.deepEqual(grid.search(1e30, 1e30, 1e30, 1e30), [0]);
  assert.deepEqual(grid.search(0, 0, Infinity, 1), []);
});
